+import express from 'express';
+
+const USUARIOS_VALIDOS = new Set([
+  'org-ana',
+  'org-bruno',
+  'p-carla',
+  'p-diego',
+  'p-elisa',
+  'p-fabio',
+  'p-gabriela',
+  'p-heitor',
+  'p-isadora',
+  'p-joao'
+]);
+
+export function criarServidor() {
+  const app = express();
+  app.use(express.json());
+
+  // Middleware de autenticação
+  app.use((req, res, next) => {
+    // Isentar rotas publicas como GET /certificados/:codigo ou /_teste/* se aplicável
+    if (req.path.startsWith('/_teste') || (req.method === 'GET' && req.path.startsWith('/certificados/'))) {
+      return next();
+    }
+
+    const usuarioHeader = req.headers['x-usuario'];
+    if (!usuarioHeader || !USUARIOS_VALIDOS.has(usuarioHeader)) {
+      return res.status(401).json({
+        erro: 'USUARIO_DESCONHECIDO',
+        mensagem: 'Usuário não identificado ou inexistente.'
+      });
+    }
+
+    req.usuario = usuarioHeader;
+    next();
+  });
+
+  return app;
+}

