import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { criarServidor } from '../api/src/app.js';

describe('Fatia 1 — Consulta de Salas e Atividades', () => {
  let server;
  let url;

  before(async () => {
    const app = criarServidor();
    await new Promise((resolve) => {
      server = app.listen(0, () => {
        const port = server.address().port;
        url = `http://localhost:${port}`;
        resolve();
      });
    });
  });

  after(async () => {
    if (server) {
      await new Promise((resolve) => server.close(resolve));
    }
  });

  it('recusa requisição sem X-Usuario com 401 USUARIO_DESCONHECIDO', async () => {
    const res = await fetch(`${url}/salas`);
    assert.equal(res.status, 401);
    const body = await res.json();
    assert.equal(body.erro, 'USUARIO_DESCONHECIDO');
  });

  it('recusa requisição com X-Usuario inexistente com 401 USUARIO_DESCONHECIDO', async () => {
    const res = await fetch(`${url}/salas`, {
      headers: { 'X-Usuario': 'usuario-fake' }
    });
    assert.equal(res.status, 401);
    const body = await res.json();
    assert.equal(body.erro, 'USUARIO_DESCONHECIDO');
  });
});

import express from 'express';

const USUARIOS_VALIDOS = new Set([
  'org-ana',
  'org-bruno',
  'p-carla',
  'p-diego',
  'p-elisa',
  'p-fabio',
  'p-gabriela',
  'p-heitor',
  'p-isadora',
  'p-joao'
]);

export function criarServidor() {
  const app = express();
  app.use(express.json());

  // Middleware de autenticação
  app.use((req, res, next) => {
    // Isentar rotas publicas como GET /certificados/:codigo ou /_teste/* se aplicável
    if (req.path.startsWith('/_teste') || (req.method === 'GET' && req.path.startsWith('/certificados/'))) {
      return next();
    }

    const usuarioHeader = req.headers['x-usuario'];
    if (!usuarioHeader || !USUARIOS_VALIDOS.has(usuarioHeader)) {
      return res.status(401).json({
        erro: 'USUARIO_DESCONHECIDO',
        mensagem: 'Usuário não identificado ou inexistente.'
      });
    }

    req.usuario = usuarioHeader;
    next();
  });

  return app;
}

import { criarServidor } from './app.js';

const PORT = process.env.PORT || 3000;
const app = criarServidor();

app.listen(PORT, () => {
  console.log(`API rodando na porta ${PORT}`);
});

